228:   if (!last) {
229:     ctx.save();
230:     ctx.translate(w / 2, h / 2);
231:     ctx.setLineDash([4, 10]);
232:     ctx.strokeStyle = 'rgba(255,77,31,.28)';
233:     ctx.lineWidth = 1.5;
234:     ctx.beginPath();
235:     ctx.ellipse(0, 0, w * 0.33, h * 0.27, -0.18, 0, TAU);
236:     ctx.stroke();
237:     ctx.setLineDash([]);
238:     ctx.strokeStyle = 'rgba(255,255,255,.08)';
239:     ctx.beginPath(); ctx.moveTo(-9, 0); ctx.lineTo(9, 0); ctx.moveTo(0, -9); ctx.lineTo(0, 9); ctx.stroke();
240:     ctx.restore();
241:     return;
242:   }
243: 
244:   const preview = analyzePreview(last.points, { targetLength: 1900 });
245:   if (!preview.prepared.length) return;
246:   let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
247:   for (const p of preview.prepared) {
248:     minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x);
249:     minY = Math.min(minY, p.y); maxY = Math.max(maxY, p.y);
250:   }
251:   const pad = 30;
252:   const scale = Math.min((w - pad * 2) / (maxX - minX || 1), (h - pad * 2) / (maxY - minY || 1));
253:   const ox = (w - (maxX - minX) * scale) / 2 - minX * scale;
254:   const oy = (h - (maxY - minY) * scale) / 2 - minY * scale;
255:   const map = (p) => ({ x: p.x * scale + ox, y: p.y * scale + oy });
256: 
257:   ctx.save();
258:   ctx.lineJoin = 'round';
259:   ctx.lineCap = 'round';
260:   ctx.beginPath();
261:   preview.prepared.forEach((p, i) => {
262:     const q = map(p);
263:     if (i === 0) ctx.moveTo(q.x, q.y); else ctx.lineTo(q.x, q.y);
264:   });
265:   ctx.closePath();
266:   ctx.strokeStyle = 'rgba(255,77,31,.16)';
267:   ctx.lineWidth = 13;
268:   ctx.shadowColor = 'rgba(255,77,31,.7)';
269:   ctx.shadowBlur = 18;
270:   ctx.stroke();
271:   ctx.shadowBlur = 0;
272:   ctx.strokeStyle = 'rgba(7,9,12,.9)';
273:   ctx.lineWidth = 7;
274:   ctx.stroke();
275:   ctx.strokeStyle = '#f3efe5';
276:   ctx.lineWidth = 2.4;
277:   ctx.stroke();
