input.content:
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { createRequire } from 'node:module';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
const launchOptions = { ...config.browser.launchOptions, headless: false };
delete launchOptions.channel;
try { process.env.DISPLAY = `:${readFileSync(join(runtime, 'display'), 'utf8').trim()}`; } catch {}
launchOptions.executablePath = '/opt/google/chrome/chrome';
const browser = await chromium.launch(launchOptions);
const page = await browser.newPage({ viewport: { width: Number(process.env.W || 1280), height: Number(process.env.H || 800) }, deviceScaleFactor: 1 });
const errs = [];
page.on('pageerror', (e) => errs.push('pageerror: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errs.push('console: ' + m.text()); });
await page.goto(process.env.URL || 'http://localhost:3000/?demo=race', { waitUntil: 'load', timeout: 60000 });
await page.waitForFunction(() => window.__apex && getComputedStyle(document.querySelector('#loading')).display === 'none', null, { timeout: 45000 });
await page.waitForTimeout(1200);
const result = await page.evaluate(process.env.JS || 'null');
console.log(JSON.stringify(result, null, 2));
if (errs.length) console.log('ERRORS:\n' + errs.join('\n'));
await browser.close();

